export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'
const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdChar = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const RADIX = { x: isHex, b: (c) => c === '0' || c === '1', o: (c) => c !== undefined && c >= '0' && c <= '7' }

export function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  let i = 0
  let line = 1
  let col = 1
  const tokens = []

  function adv() {
    const c = cs[i++]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }

  // digit run with single underscores between digits; returns consumed text
  function run(isD) {
    let s = ''
    if (!isD(cs[i])) return s
    while (i < n) {
      if (isD(cs[i])) s += adv()
      else if (cs[i] === '_' && isD(cs[i + 1]) && isD(cs[i - 1])) s += adv()
      else break
    }
    return s
  }

  function number(l, c) {
    let s = ''
    let ok = true
    if (cs[i] === '0' && cs[i + 1] !== undefined && /^[xXbBoO]$/.test(cs[i + 1])) {
      s += adv()
      const d = RADIX[adv().toLowerCase()]
      s = cs.slice(i - 2, i).join('')
      const r = run(d)
      if (r === '') ok = false
      s += r
    } else {
      s += run(isDigit)
      if (cs[i] === '.' && isDigit(cs[i + 1])) {
        s += adv()
        s += run(isDigit)
      }
      if (cs[i] === 'e' || cs[i] === 'E') {
        const a = cs[i + 1]
        if (isDigit(a) || ((a === '+' || a === '-') && isDigit(cs[i + 2]))) {
          s += adv()
          if (!isDigit(cs[i])) s += adv()
          s += run(isDigit)
        }
      }
    }
    if (!ok || isIdChar(cs[i])) {
      while (isIdChar(cs[i])) s += adv()
      throw new ScanError(l, c, `invalid number ${s}`)
    }
    tokens.push({ line: l, col: c, kind: 'number', body: s })
  }

  function string(l, c) {
    adv()
    let v = ''
    for (;;) {
      if (i >= n) throw new ScanError(l, c, 'unterminated string')
      const el = line
      const ec = col
      const ch = adv()
      if (ch === '"') break
      if (ch === '\n') throw new ScanError(el, ec, 'newline in string')
      if (ch !== '\\') {
        v += ch
        continue
      }
      if (i >= n) throw new ScanError(l, c, 'unterminated string')
      const e = adv()
      const bad = () => new ScanError(el, ec, `invalid escape \\${e}`)
      if (e === 'n') v += '\n'
      else if (e === 't') v += '\t'
      else if (e === 'r') v += '\r'
      else if (e === '\\') v += '\\'
      else if (e === '"') v += '"'
      else if (e === '0') v += '\0'
      else if (e === 'x') {
        if (!isHex(cs[i]) || !isHex(cs[i + 1])) throw bad()
        v += String.fromCharCode(parseInt(adv() + adv(), 16))
      } else if (e === 'u') {
        if (cs[i] !== '{') throw bad()
        let j = i + 1
        let h = ''
        while (isHex(cs[j])) h += cs[j++]
        if (h === '' || cs[j] !== '}' || parseInt(h, 16) > 0x10ffff) throw bad()
        while (i <= j) adv()
        v += String.fromCodePoint(parseInt(h, 16))
      } else throw bad()
    }
    tokens.push({ line: l, col: c, kind: 'string', body: JSON.stringify(v) })
  }

  while (i < n) {
    const ch = cs[i]
    const l = line
    const c = col
    if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') {
      adv()
    } else if (ch === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
    } else if (ch === '/' && cs[i + 1] === '*') {
      adv()
      adv()
      let depth = 1
      while (depth > 0) {
        if (i >= n) throw new ScanError(l, c, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') {
          adv()
          adv()
          depth++
        } else if (cs[i] === '*' && cs[i + 1] === '/') {
          adv()
          adv()
          depth--
        } else adv()
      }
    } else if (ch === 'r' && cs[i + 1] === '"') {
      adv()
      adv()
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(l, c, 'unterminated string')
        const x = adv()
        if (x === '"') break
        v += x
      }
      tokens.push({ line: l, col: c, kind: 'rawstring', body: JSON.stringify(v) })
    } else if (isIdStart(ch)) {
      let s = ''
      while (isIdChar(cs[i])) s += adv()
      tokens.push({ line: l, col: c, kind: KEYWORDS.has(s) ? 'keyword' : 'ident', body: s })
    } else if (isDigit(ch)) {
      number(l, c)
    } else if (ch === '"') {
      string(l, c)
    } else {
      const two = ch + (cs[i + 1] ?? '')
      if (PUNCT2.includes(two)) {
        adv()
        adv()
        tokens.push({ line: l, col: c, kind: 'punct', body: two })
      } else if (PUNCT1.includes(ch)) {
        adv()
        tokens.push({ line: l, col: c, kind: 'punct', body: ch })
      } else throw new ScanError(l, c, `unexpected character ${ch}`)
    }
  }
  return tokens
}
